import test from 'node:test';
import assert from 'node:assert/strict';
import { normalize } from '../src/normalize.js';

test('trims surrounding whitespace and lowercases letters', () => {
  assert.equal(normalize(' \tHeLLo WoRLD\n'), 'hello world');
});

test('preserves internal whitespace while lowercasing', () => {
  assert.equal(normalize(' A  B\tC\nD '), 'a  b\tc\nd');
});

test('accepts empty input', () => {
  assert.equal(normalize(''), '');
});

test('returns empty for all-whitespace input', () => {
  assert.equal(normalize(' \t\r\n '), '');
});

test('leaves lowercase text unchanged', () => {
  assert.equal(normalize('hello'), 'hello');
});

const invalidInputs = [
  ['undefined', undefined],
  ['null', null],
  ['false', false],
  ['true', true],
  ['zero', 0],
  ['negative number', -1],
  ['fractional number', 1.5],
  ['NaN', NaN],
  ['Infinity', Infinity],
  ['bigint', 1n],
  ['symbol', Symbol('text')],
  ['empty array', []],
  ['string array', ['hello']],
  ['plain object', {}],
  ['function', () => 'hello'],
  ['boxed string', new String('hello')],
];

for (const [label, value] of invalidInputs) {
  test(`throws TypeError for ${label}`, () => {
    assert.throws(() => normalize(value), TypeError);
  });
}

test('throws TypeError for an omitted argument', () => {
  assert.throws(() => normalize(), TypeError);
});

